# Phase 4C native multi-track workflow. Dot-sourced by mix-ui.ps1 through
# filmstrip-ui.ps1 -Perf -Stage (helpers and the foreground guard).
# Sources (generated by mix-ui.ps1): a 30 s 720p H.264 film with AAC streams at
# 400 Hz (primary) and 1200 Hz (alternate), and an 800 Hz WAV. Frequencies are
# multiples of 100 Hz so 10 ms loopback windows separate them cleanly. Every
# level below is measured from the Windows output by WASAPI loopback.
. "$PSScriptRoot\av-common.ps1"
$sources = Join-Path $repo '.artifacts\av\sources-mix'
foreach ($n in 'mix film.mp4', 'mix music.wav') { Copy-Item (Join-Path $sources $n) (Join-Path $work $n) }
$film = Join-Path $work 'mix film.mp4'; $music = Join-Path $work 'mix music.wav'
$project = Join-Path $work 'mix session.cutcap'
$Tones = '400,800,1200'
$results = [ordered]@{}

function Levels($rec, [double]$from, [double]$to) {
  [ordered]@{ a400 = Tone-Mean $rec '400' $from $to; a800 = Tone-Mean $rec '800' $from $to; a1200 = Tone-Mean $rec '1200' $from $to }
}
function Show($label, $l) { Note "$label : 400 Hz $($l.a400)  800 Hz $($l.a800)  1200 Hz $($l.a1200)" }
function Named([IntPtr]$h, [string]$name) { @(All-Elements $h | Where-Object { $_.Current.Name -eq $name -and (Visible $_) }).Count -gt 0 }

$env:CUTCAP_TRACE_AUDIO = '1'
$script:launch = 1
$app = Start-App; $h = $app.H; $trace = "$Shots\app-out-$($script:launch - 1).txt"
$env:CUTCAP_TRACE_AUDIO = $null
Note "scale=$(Scale $h)"

# 1-2. Import the film and place its linked pair by drag.
Import $h $app.P.Id $film
$from = Tile $h 'mix film' 'mix film.mp4'
Drag-Points $from (Lane-Point $h 300 0) 30
Clear-Search $h
Note "1-2 linked pair placed: $(Wait-Lanes $h '2 clips')"
# 3-4. Import the audio-only file; drag it onto a new Audio 2.
Import $h $app.P.Id $music
Note "3 audio-only tile, inspector: '$((All-Elements $h | Where-Object { $_.Current.Name -like '* Hz *' } | Select-Object -First 1).Current.Name)' source monitor: $(Named $h 'Audio-only source')"
Save-Client $h "$Shots\01-audio-only-source.jpg"
Click-Named $h 'Add audio track'; Start-Sleep -Milliseconds 700
$from = Tile $h 'mix music' 'mix music.wav'
Drag-Points $from (Lane-Point $h 300 2) 30
Clear-Search $h
Note "4 audio-only placed on Audio 2: $(Wait-Lanes $h '3 clips')"
Start-Sleep -Milliseconds 4000
Click-Named $h 'Media collections'
$w1 = Wave-Pixels $h 1000 15000 1; $w2 = Wave-Pixels $h 1000 15000 2
Note "4 waveform pixels: Audio 1 $($w1.Wave), Audio 2 $($w2.Wave)"
Save-Client $h "$Shots\02-two-waveforms.jpg"

# 5-10. One continuous playback with the controls changed live.
Click-Point (Ruler-Point $h 1000); Start-Sleep -Milliseconds 1200
$rec = Start-ToneRecorder 'controls' 29 $Tones
Start-Sleep -Milliseconds 500
$t = [ordered]@{}
$t.play = Timed-Click $h 'Play timeline'
Start-Sleep -Milliseconds 3000
Save-Client $h "$Shots\03-playing-two-tracks.jpg"
$t.gain = Drag-Gain $h 'Audio 2' 0 -12
$gainAfter = Gain-Text $h 'Audio 2'
$undoAfterDrag = Undo-Tip $h
Start-Sleep -Milliseconds 2200
$t.mute = Timed-Click $h 'Mute Audio 1'
Start-Sleep -Milliseconds 2200
Save-Client $h "$Shots\04-muted.jpg"
$t.solo = Timed-Click $h 'Solo Audio 1'
Start-Sleep -Milliseconds 2200
$t.unmute = Timed-Click $h 'Unmute Audio 1'
Start-Sleep -Milliseconds 2200
Save-Client $h "$Shots\05-soloed.jpg"
$t.unsolo = Timed-Click $h 'Remove solo from Audio 1'
Start-Sleep -Milliseconds 2200
$t.restore = Drag-Gain $h 'Audio 2' -12 0
Start-Sleep -Milliseconds 1500
$t.pause = Timed-Click $h 'Pause timeline'
$heard = Read-Recorder $rec 'controls'
Note "drag result: '$gainAfter'; undo offers: '$undoAfterDrag'; playback state unchanged by controls"
$both = Levels $heard ($t.play + 1200) ($t.gain - 300)
Show '6 both tracks' $both
$cut = Levels $heard ($t.gain + 600) ($t.mute - 100)
Show '7 Audio 2 lowered' $cut
Note "7 Audio 2 change measured $(Db ($cut.a800 / $both.a800)) dB (engine: $gainAfter); Audio 1 change $(Db ($cut.a400 / $both.a400)) dB"
$muted = Levels $heard ($t.mute + 600) ($t.solo - 100)
Show '8 Audio 1 muted' $muted
$mutesolo = Levels $heard ($t.solo + 600) ($t.unmute - 100)
Show '9 Audio 1 muted and soloed (mute wins, others silenced)' $mutesolo
$solo = Levels $heard ($t.unmute + 600) ($t.unsolo - 100)
Show '9 Audio 1 soloed' $solo
$restored = Levels $heard ($t.restore + 600) ($t.pause - 100)
Show '10 restored' $restored
$results.controls = [ordered]@{ both = $both; cut = $cut; muted = $muted; mute_and_solo = $mutesolo; solo = $solo; restored = $restored }
# Control latency: press to the moment the loopback tap shows the change.
$lat = [ordered]@{}
$lat.mute_ms = [Math]::Round((Tone-Cross $heard '400' $t.mute ($both.a400 / 2) $false) - $t.mute)
$lat.unmute_ms = [Math]::Round((Tone-Cross $heard '400' $t.unmute ($both.a400 / 2) $true) - $t.unmute)
$lat.solo_silences_other_ms = [Math]::Round((Tone-Cross $heard '800' $t.solo ($muted.a800 / 2) $false) - $t.solo)
$lat.gain_restore_ms = [Math]::Round((Tone-Cross $heard '800' $t.restore ((($restored.a800 + $cut.a800) / 2)) $true) - $t.restore)
$results.control_latency_ms = $lat
Note "control latency (press to loopback tap): mute $($lat.mute_ms) ms, unmute $($lat.unmute_ms) ms, solo $($lat.solo_silences_other_ms) ms, volume $($lat.gain_restore_ms) ms"
Note "first audio latency: play to 400 Hz at loopback $([Math]::Round((Tone-Cross $heard '400' $t.play ($both.a400 / 2) $true 4000) - $t.play)) ms"

# 11. Unlink the pair (selected through the audio clip).
Click-Point (Lane-Point $h 5000 1); Start-Sleep -Milliseconds 500
Note "11 before unlink, button enabled: $((Find-Element $h 'Unlink audio and video').Current.IsEnabled)"
Click-Named $h 'Unlink audio and video'; Start-Sleep -Milliseconds 700
Note "11 after unlink, button enabled: $((Find-Element $h 'Unlink audio and video').Current.IsEnabled); undo offers '$(Undo-Tip $h)'; re-link offered: $(Named $h 'Link clip')"
Save-Client $h "$Shots\06-unlinked.jpg"
# 12. Move only the audio by 2 s.
Drag-Points (Lane-Point $h 5000 1) (Lane-Point $h 7000 1)
Note "12 audio moved alone: $(Wait-Lanes $h '00:02.000 to 00:32.000')"
# 13. Trim its start by 1 s, then split at 10 s.
$p0 = Lane-Point $h 2000 1; $p0.X += [int](3 * (Scale $h))
Drag-Points $p0 (Lane-Point $h 3000 1) 20
Note "13 trimmed: $(Wait-Lanes $h '00:03.000 to 00:32.000')"
Click-Point (Ruler-Point $h 10000); Start-Sleep -Milliseconds 900
Click-Point (Lane-Point $h 6000 1); Click-Named $h 'Media collections'
Send-Key $h 'CTRL+B'; Note "13 split: $(Wait-Lanes $h '4 clips')"
Start-Sleep -Milliseconds 2000
Save-Client $h "$Shots\07-independent-edits.jpg"
# 14. Undo the split and trim, redo them.
Send-Key $h 'CTRL+Z'; Note "14 undo split: $(Wait-Lanes $h '3 clips')"
Send-Key $h 'CTRL+Z'; Note "14 undo trim: $(Wait-Lanes $h '00:02.000 to 00:32.000')"
Send-Key $h 'CTRL+Y'; Note "14 redo trim: $(Wait-Lanes $h '00:03.000 to 00:32.000')"
Send-Key $h 'CTRL+Y'; Note "14 redo split: $(Wait-Lanes $h '4 clips')"
# 15. The film's alternate stream, placed explicitly on a new Audio 3 at 0.
Click-Point (Ruler-Point $h 0); Start-Sleep -Milliseconds 900
Click-Named $h 'Add audio track'; Start-Sleep -Milliseconds 700
Select-Source $h 'mix film' 'mix film.mp4'
Start-Sleep -Milliseconds 600
Save-Client $h "$Shots\08-stream-chooser.jpg"
Click-Named $h 'Place audio stream 2 on the timeline'
Note "15 alternate stream placed: $(Wait-Lanes $h '5 clips')"
Start-Sleep -Milliseconds 3000
Click-Named $h 'Media collections'
$w3 = Wave-Pixels $h 1000 15000 3
Note "15 Audio 3 waveform pixels: $($w3.Wave)"
Save-Client $h "$Shots\09-three-audio-tracks.jpg"
Click-Point (Ruler-Point $h 12000); Start-Sleep -Milliseconds 1200
$r = Start-ToneRecorder 'three' 6 $Tones
Start-Sleep -Milliseconds 400
$p = Timed-Click $h 'Play timeline'
Start-Sleep -Milliseconds 4000
$e = Timed-Click $h 'Pause timeline'
$three = Levels (Read-Recorder $r 'three') ($p + 1800) ($e - 100)
Show '15 all three streams mixed' $three
$results.three_tracks = $three
# Settings to persist: Audio 2 at -6 dB, Audio 3 muted, then the same mix.
$null = Drag-Gain $h 'Audio 2' 0 -6
Click-Named $h 'Mute Audio 3'; Start-Sleep -Milliseconds 500
$settings = "$(Gain-Text $h 'Audio 2'), Audio 3 muted: $(Named $h 'Unmute Audio 3')"
Note "15 settings before save: $settings"
function Measure-Mix($label) {
  Click-Point (Ruler-Point $h 12000); Start-Sleep -Milliseconds 1200
  $r = Start-ToneRecorder $label 6 $Tones
  Start-Sleep -Milliseconds 400
  $p = Timed-Click $h 'Play timeline'
  Start-Sleep -Milliseconds 4000
  $e = Timed-Click $h 'Pause timeline'
  $d = Read-Recorder $r $label
  Levels $d ($p + 1800) ($e - 100)
}
$beforeSave = Measure-Mix 'before-save'
Show '15 mix before save (12 s on)' $beforeSave

# 16-18. Save, close, reopen: same mix and settings.
Send-Key $h 'CTRL+SHIFT+S'; Start-Sleep -Milliseconds 900
Complete-Dialog $app.P.Id 'Save CutCap project' $project; Start-Sleep -Milliseconds 2000
$doc = Get-Content -LiteralPath $project -Raw -Encoding utf8 | ConvertFrom-Json
Note "16 saved schema $($doc.project.schema_version): $(@($doc.project.tracks | ForEach-Object { "$($_.name):$($_.controls | ConvertTo-Json -Compress)" }) -join ' ; ')"
Note "16 clips: $(@($doc.project.clips | ForEach-Object { "$($_.stream.kind)$(if ($_.stream.index) { '#' + $_.stream.index })@$($_.start)+$($_.duration)$(if ($_.link) { ' link' })" }) -join ' ; ')"
$hash = (Get-FileHash -LiteralPath $project).Hash
Close-App $app 'close after save'
$env:CUTCAP_TRACE_AUDIO = '1'
$app = Start-App; $h = $app.H
$env:CUTCAP_TRACE_AUDIO = $null
Open-Project $h $app.P.Id
Note "17 reopened: $(Wait-Lanes $h '5 clips' 15000)"
Start-Sleep -Milliseconds 7000
Click-Named $h 'Media collections'
Note "18 waveforms after reopen: Audio 1 $((Wave-Pixels $h 12000 20000 1).Wave), Audio 2 $((Wave-Pixels $h 1000 15000 2).Wave), Audio 3 (muted, dimmed) $((Wave-Pixels $h 1000 15000 3 0.5).Wave); settings: $(Gain-Text $h 'Audio 2'), Audio 3 muted: $(Named $h 'Unmute Audio 3')"
Save-Client $h "$Shots\10-reopened.jpg"
$afterOpen = Measure-Mix 'after-open'
Show '18 mix after reopen' $afterOpen
Note "18 level change after reopen: 400 Hz $(Db ($afterOpen.a400 / $beforeSave.a400)) dB, 800 Hz $(Db ($afterOpen.a800 / $beforeSave.a800)) dB; 1200 Hz (muted) $($afterOpen.a1200); file unchanged: $((Get-FileHash -LiteralPath $project).Hash -eq $hash)"
$results.persistence = [ordered]@{ before_save = $beforeSave; after_open = $afterOpen }
Close-App $app 'close after reopen'

# 19. Genuine older projects.
$legacy = Join-Path $repo '.artifacts\av\legacy'
$one = Join-Path $work 'phase3d two-source.cutcap'
Copy-Item (Join-Path $repo '.artifacts\phase3d\native-two-source.cutcap') $one
Copy-Item (Join-Path $repo '.artifacts\phase3d\native-media') (Join-Path $work 'native-media') -Recurse
$two = Join-Path $work 'phase4b schema2.cutcap'
Copy-Item (Join-Path $legacy 'schema2.cutcap') $two
Copy-Item (Join-Path $legacy 'av moved.mp4') (Join-Path $work 'av moved.mp4')
foreach ($old in @(@{ File = $one; Clips = '2 clips'; Schema = 1 }, @{ File = $two; Clips = '4 clips'; Schema = 2 })) {
  $oldHash = (Get-FileHash -LiteralPath $old.File).Hash
  $app = Start-App; $h = $app.H
  $project = $old.File
  Open-Project $h $app.P.Id
  Note "19 schema $($old.Schema) project: $(Wait-Lanes $h $old.Clips 15000)"
  Start-Sleep -Milliseconds 3500
  Save-Client $h "$Shots\11-schema$($old.Schema).jpg"
  Click-Point (Ruler-Point $h 500); Start-Sleep -Milliseconds 1000
  $r = Start-ToneRecorder "old$($old.Schema)" 3 $Tones
  Start-Sleep -Milliseconds 300
  $null = Timed-Click $h 'Play timeline'
  Start-Sleep -Milliseconds 2000
  $null = Timed-Click $h 'Pause timeline'
  $d = Read-Recorder $r "old$($old.Schema)"
  Note "19 schema $($old.Schema): played, playhead $(Playhead $h), output rms $($d.rms); file unchanged by opening: $((Get-FileHash -LiteralPath $old.File).Hash -eq $oldHash)"
  Close-App $app "close schema $($old.Schema)"
}

# 20-21. Close while three decoders run; nothing may remain.
$project = Join-Path $work 'mix session.cutcap'
$app = Start-App; $h = $app.H
Open-Project $h $app.P.Id
$null = Wait-Lanes $h '5 clips' 15000
Start-Sleep -Milliseconds 2500
Click-Point (Ruler-Point $h 2000); Start-Sleep -Milliseconds 800
Click-Named $h 'Play timeline'; Start-Sleep -Milliseconds 1500
Note "20 decoders running before close: $(@(Get-Process ffmpeg -ErrorAction SilentlyContinue).Count) FFmpeg processes"
Close-App $app 'close during multi-track decoding'
$after = Start-ToneRecorder 'after-close' 2 $Tones
$after = Read-Recorder $after 'after-close'
Note "21 after close: CutCap/FFmpeg/FFprobe processes=$(@(Get-Process CutCap, ffmpeg, ffprobe -ErrorAction SilentlyContinue).Count), output rms=$($after.rms) (silent: endpoint released)"
$results | ConvertTo-Json -Depth 6 | Set-Content "$Shots\mix-results.json" -Encoding utf8
$log | Set-Content "$Shots\mix-scenario.txt" -Encoding utf8
